#ifndef SCAMP_PREFIX_HPP
#define SCAMP_PREFIX_HPP
#include "scamptrie_base.h"
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <vector>

// A normalized prefix together with the forwarding value stored for it.
struct IPPrefix {
    ip6_t address;
    uint8_t length;
    uint32_t hop;
};

inline ip6_t mask_ip6(ip6_t ip, unsigned length) {
    if (length == 0) return ip6_t{0, 0};
    if (length < 64) return ip6_t{ip.hi & (~0ULL << (64 - length)), 0};
    if (length == 64) return ip6_t{ip.hi, 0};
    if (length < 128) return ip6_t{ip.hi, ip.lo & (~0ULL << (128 - length))};
    return ip;
}

inline IPPrefix make_prefix(ip6_t address, unsigned length, uint32_t hop) {
    IPPrefix p;
    p.address = mask_ip6(address, length);
    p.length = static_cast<uint8_t>(length);
    p.hop = hop;
    return p;
}

inline bool prefix_entry_less(const IPPrefix& a, const IPPrefix& b) {
    if (a.length != b.length) return a.length < b.length;
    if (a.address.hi != b.address.hi) return a.address.hi < b.address.hi;
    return a.address.lo < b.address.lo;
}

inline bool prefix_entry_equal(const IPPrefix& a, const IPPrefix& b) {
    return a.length == b.length && a.address.hi == b.address.hi &&
           a.address.lo == b.address.lo;
}

inline bool get_prefix_bit(const ip6_t& ip, int pos) {
    if (pos < 64) return ((ip.hi >> (63 - pos)) & 1ULL) != 0;
    return ((ip.lo >> (127 - pos)) & 1ULL) != 0;
}

inline void set_prefix_bit(ip6_t& ip, int pos, bool value) {
    if (pos < 64) {
        uint64_t bit = 1ULL << (63 - pos);
        if (value) ip.hi |= bit; else ip.hi &= ~bit;
    } else {
        uint64_t bit = 1ULL << (127 - pos);
        if (value) ip.lo |= bit; else ip.lo &= ~bit;
    }
}

// Extract up to 64 bits starting at MSB position pos (bit 0 is the address MSB).
inline uint64_t extract_prefix_bits(const ip6_t& ip, int pos, int count) {
    uint64_t value = 0;
    for (int i = 0; i < count; ++i)
        value = (value << 1) | (get_prefix_bit(ip, pos + i) ? 1ULL : 0ULL);
    return value;
}

// Build a prefix from a node-region address whose bits below region_depth are
// zero and a short local fragment beginning at region_depth.
inline ip6_t make_local_prefix(const ip6_t& region, int region_depth,
                               int local_length, uint64_t local_value) {
    ip6_t out = region;
    for (int i = 0; i < local_length; ++i) {
        bool bit = ((local_value >> (local_length - 1 - i)) & 1ULL) != 0;
        set_prefix_bit(out, region_depth + i, bit);
    }
    return out;
}

inline bool prefix_in_region(const ip6_t& prefix, unsigned prefix_length,
                             const ip6_t& region, unsigned region_depth) {
    if (prefix_length < region_depth) return false;
    ip6_t a = mask_ip6(prefix, region_depth);
    ip6_t b = mask_ip6(region, region_depth);
    return a.hi == b.hi && a.lo == b.lo;
}

struct PrefixKey {
    uint8_t length;
    uint64_t hi;
    uint64_t lo;
    bool operator==(const PrefixKey& other) const {
        return length == other.length && hi == other.hi && lo == other.lo;
    }
};

struct PrefixKeyHash {
    size_t operator()(const PrefixKey& k) const {
        uint64_t x = k.hi + 0x9e3779b97f4a7c15ULL;
        x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
        x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
        x ^= x >> 31;
        uint64_t y = k.lo + 0x9e3779b97f4a7c15ULL + (x << 6) + (x >> 2);
        y = (y ^ (y >> 30)) * 0xbf58476d1ce4e5b9ULL;
        y = (y ^ (y >> 27)) * 0x94d049bb133111ebULL;
        y ^= y >> 31;
        return static_cast<size_t>(x ^ y ^ (static_cast<uint64_t>(k.length) << 56));
    }
};

#endif
