#ifndef SCAMP_FIB_HPP
#define SCAMP_FIB_HPP
#include "prefix.hpp"
#include <unordered_map>
#include <vector>

class FibTable {
public:
    void put(ip6_t address, unsigned length, uint32_t hop) {
        IPPrefix p = make_prefix(address, length, hop);
        PrefixKey key{p.length, p.address.hi, p.address.lo};
        map_[key] = hop;
    }

    nexthop_t lookup(const ip6_t& address) const {
        for (int length = 128; length >= 0; --length) {
            ip6_t masked = mask_ip6(address, static_cast<unsigned>(length));
            PrefixKey key{static_cast<uint8_t>(length), masked.hi, masked.lo};
            auto it = map_.find(key);
            if (it != map_.end()) return it->second;
        }
        return LPM_INVALID_NH;
    }

    size_t size() const { return map_.size(); }

    std::vector<IPPrefix> entries() const {
        std::vector<IPPrefix> out;
        out.reserve(map_.size());
        for (const auto& item : map_) {
            IPPrefix p;
            p.length = item.first.length;
            p.address.hi = item.first.hi;
            p.address.lo = item.first.lo;
            p.hop = item.second;
            out.push_back(p);
        }
        std::sort(out.begin(), out.end(), prefix_entry_less);
        return out;
    }

private:
    std::unordered_map<PrefixKey, uint32_t, PrefixKeyHash> map_;
};

#endif
